//! The measured registry. It ships as a data file (`data/registry.txt`,
//! generated by `tools/registry_to_data.py` from `appfunctions-registry.xml`)
//! and is embedded into the binary at build time.
//!
//! Every entry carries its origin (`source`): `dump` (runtime metadata of the
//! device), `schema` (asset/app_function.xml of the target APK), `call-ok` (a
//! call went through with these values), `error-message` (the target app named
//! the field), `convention` or `assumed` (guessed - this is shown to the user).

pub const REGISTRY: &str = include_str!("../data/registry.txt");

#[derive(Debug, Clone, PartialEq)]
pub struct Field {
    pub name: String,
    pub data_type: String,
    pub required: bool,
    pub source: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Parameter {
    pub name: String,
    pub type_name: String,
    /// `top-level` if the parameter itself sits at the top level
    /// (e.g. `personIds`), empty otherwise.
    pub level: String,
    pub source: String,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Function {
    pub package: String,
    pub id: String,
    pub name: String,
    pub category: String,
    pub status: String,
    pub verified: bool,
    pub parameters: Vec<Parameter>,
    pub example: Option<String>,
    /// From the B line: the arguments and the origin, kept apart (for `probes`).
    pub example_args: String,
    pub example_source: String,
}

impl Function {
    pub fn short_name(&self) -> &str {
        self.id.rsplit('#').next().unwrap_or(&self.id)
    }

    /// The parameter whose fields are given at the top level (exactly one in
    /// this registry). Composite parameters carry a class name as their type,
    /// flat ones a descriptive one (`text`, `list-of-text`).
    pub fn composite(&self) -> Option<&Parameter> {
        self.parameters
            .iter()
            .find(|p| p.level != "top-level" && !p.type_name.contains("text") && p.type_name.contains('.'))
    }

    pub fn flat(&self) -> Vec<&Parameter> {
        self.parameters
            .iter()
            .filter(|p| p.level == "top-level" || p.type_name == "text" || p.type_name == "list-of-text")
            .collect()
    }

    pub fn is_read_only(&self) -> bool {
        let n = self.short_name().to_lowercase();
        let n = n.rsplit('_').next().unwrap_or(&n);
        ["find", "get", "search", "list", "is", "query", "read", "lookup", "fetch"]
            .iter()
            .any(|v| n.starts_with(v))
    }
}

#[derive(Debug, Clone)]
pub struct Registry {
    pub functions: Vec<Function>,
}

impl Registry {
    pub fn from_text(text: &str) -> Registry {
        let mut functions: Vec<Function> = Vec::new();
        for line in text.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let t: Vec<&str> = line.split('\t').collect();
            match t[0] {
                "F" => functions.push(Function {
                    package: field(&t, 1),
                    id: field(&t, 2),
                    name: field(&t, 3),
                    category: field(&t, 4),
                    status: field(&t, 5),
                    verified: field(&t, 6) == "yes",
                    parameters: Vec::new(),
                    example: None,
                    example_args: String::new(),
                    example_source: String::new(),
                }),
                "P" => {
                    if let Some(f) = functions.last_mut() {
                        f.parameters.push(Parameter {
                            name: field(&t, 2),
                            type_name: field(&t, 3),
                            level: field(&t, 4),
                            source: field(&t, 5),
                            fields: Vec::new(),
                        });
                    }
                }
                "D" => {
                    if let Some(f) = functions.last_mut() {
                        // D: id, parameter name, field, data type, required, source
                        let pname = field(&t, 2);
                        if let Some(p) = f.parameters.iter_mut().rev().find(|p| p.name == pname) {
                            p.fields.push(Field {
                                name: field(&t, 3),
                                data_type: field(&t, 4),
                                required: field(&t, 5) == "yes",
                                source: field(&t, 6),
                            });
                        }
                    }
                }
                "B" => {
                    if let Some(f) = functions.last_mut() {
                        f.example_args = field(&t, 2);
                        f.example_source = field(&t, 3);
                        f.example = Some(format!(
                            "{} (args: {}, source: {})",
                            field(&t, 4),
                            field(&t, 2),
                            field(&t, 3)
                        ));
                    }
                }
                _ => {}
            }
        }
        Registry { functions }
    }

    pub fn embedded() -> Registry {
        Registry::from_text(REGISTRY)
    }

    /// Looks up a function. `key` is the full path, a part of it, or the
    /// short name. Ambiguity is an error with a list of candidates, so that
    /// nothing wrong gets called.
    pub fn find(&self, package: Option<&str>, key: &str) -> Result<&Function, String> {
        let k = key.to_lowercase();
        let candidates: Vec<&Function> = self
            .functions
            .iter()
            .filter(|f| package.map_or(true, |p| f.package == p))
            .filter(|f| {
                f.id.to_lowercase() == k
                    || f.id.to_lowercase().ends_with(key)
                    || f.short_name().to_lowercase() == k
                    || f.id.to_lowercase().contains(&k)
            })
            .collect();
        match candidates.len() {
            0 => Err(format!("no function matches '{}'", key)),
            1 => Ok(candidates[0]),
            _ => {
                let exact: Vec<&&Function> = candidates
                    .iter()
                    .filter(|f| f.short_name().to_lowercase() == k)
                    .collect();
                if exact.len() == 1 {
                    return Ok(exact[0]);
                }
                Err(format!(
                    "'{}' is ambiguous:\n{}",
                    key,
                    candidates
                        .iter()
                        .map(|f| format!("  {} ({})", f.id, f.package))
                        .collect::<Vec<_>>()
                        .join("\n")
                ))
            }
        }
    }

    pub fn search(&self, pattern: &str) -> Vec<&Function> {
        let m = pattern.to_lowercase();
        self.functions
            .iter()
            .filter(|f| {
                m.is_empty()
                    || f.id.to_lowercase().contains(&m)
                    || f.package.to_lowercase().contains(&m)
                    || f.category.to_lowercase().contains(&m)
            })
            .collect()
    }
}

fn field(t: &[&str], i: usize) -> String {
    t.get(i).unwrap_or(&"").to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_loads_and_is_complete() {
        let r = Registry::embedded();
        assert_eq!(r.functions.len(), 61, "61 functions expected");
        let verified = r.functions.iter().filter(|f| f.verified).count();
        assert_eq!(verified, 13, "13 confirmed calls expected");
    }

    #[test]
    fn fields_attach_to_the_right_parameter() {
        let r = Registry::embedded();
        let f = r.find(Some("com.samsung.android.app.contacts"), "findPersons").unwrap();
        let c = f.composite().expect("findPersonsParams expected");
        assert_eq!(c.name, "findPersonsParams");
        assert!(c.fields.iter().any(|x| x.name == "maxCount" && x.required));
        assert!(c.fields.iter().any(|x| x.name == "query" && !x.required));
    }

    #[test]
    fn person_ids_are_top_level() {
        let r = Registry::embedded();
        let f = r.find(Some("com.samsung.android.app.contacts"), "getPersons").unwrap();
        let flat = f.flat();
        assert_eq!(flat.len(), 1);
        assert_eq!(flat[0].name, "personIds");
        assert!(f.composite().is_none());
    }

    #[test]
    fn ambiguous_short_name_is_an_error() {
        // getPersons exists in both Contacts and the dialer.
        let r = Registry::embedded();
        assert!(r.find(None, "getPersons").is_err());
        assert!(r.find(Some("com.samsung.android.dialer"), "getPersons").is_ok());
    }

    #[test]
    fn read_only_and_writing() {
        let r = Registry::embedded();
        assert!(r.find(None, "findBookmarks").unwrap().is_read_only());
        assert!(r.find(None, "getHistories").unwrap().is_read_only());
        assert!(!r.find(None, "createAlbum").unwrap().is_read_only());
        assert!(!r.find(None, "showSite").unwrap().is_read_only());
    }
}
